      "id": "2606.10217",
      "direction_id": "agent-policy-optimization",
      "direction_name": "Agent 策略优化与在线蒸馏",
      "week": "2026-W24",
      "title": "Alignment Defends LLMs from Property Inference Attacks",
      "title_zh": "对齐防御可保护大语言模型免受属性推断攻击",
      "authors": [
        "Pengrun Huang",
        "Chhavi Yadav",
        "Ruihan Wu",
        "Kamalika Chaudhuri"
      ],
      "url": "http://arxiv.org/abs/2606.10217v1",
      "pdf_url": "https://arxiv.org/pdf/2606.10217v1",
